/// PawTable Firebase default platform options
///
/// Generated by `flutterfire configure` — or you can create these
/// manually. This file provides the [DefaultFirebaseOptions] class
/// which is required by [Firebase.initializeApp()].
///
/// TO SET UP:
/// 1. Create a Firebase project at https://console.firebase.google.com
/// 2. Add an Android app (package: com.pawtable) and download google-services.json
/// 3. Add an iOS app (bundle: com.pawtable.app) and download GoogleService-Info.plist
/// 4. Run: `flutterfire configure` (recommended) or copy values below
/// 5. Replace the placeholder values with your actual project configuration
library;

import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show kIsWeb, TargetPlatform, defaultTargetPlatform;

/// Default Firebase options — override with `flutterfire configure`
///
/// These values are placeholders. Replace them with your actual
/// Firebase project configuration.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      return web;
    }

    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        return ios;
      case TargetPlatform.macOS:
        return macos;
      case TargetPlatform.windows:
        return windows;
      case TargetPlatform.linux:
        throw UnsupportedError(
          'Detected TargetPlatform.linux but no Firebase options for linux were found.',
        );
      default:
        throw UnsupportedError(
          'DefaultFirebaseOptions have not been configured for $defaultTargetPlatform',
        );
    }
  }

  // -----------------------------------------------------------------------
  // ANDROID
  // -----------------------------------------------------------------------

  /// Android Firebase configuration
  ///
  /// TO CONFIGURE: Replace with values from your Firebase Console
  /// > Project Settings > Your apps > Android app > Configuration
  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'YOUR_ANDROID_API_KEY',
    appId: '1:YOUR_PROJECT_ID:android:YOUR_ANDROID_MESSAGE_BINDING_HASH',
    messagingSenderId: 'YOUR_SENDER_ID',
    projectId: 'YOUR_PROJECT_ID',
    storageBucket: 'YOUR_PROJECT_ID.appspot.com',
  );

  // -----------------------------------------------------------------------
  // iOS
  // -----------------------------------------------------------------------

  /// iOS Firebase configuration
  ///
  /// TO CONFIGURE: Replace with values from GoogleService-Info.plist
  static const FirebaseOptions ios = FirebaseOptions(
    apiKey: 'YOUR_IOS_API_KEY',
    appId: '1:YOUR_PROJECT_ID:ios:YOUR_IOS_MESSAGE_BINDING_HASH',
    messagingSenderId: 'YOUR_SENDER_ID',
    projectId: 'YOUR_PROJECT_ID',
    storageBucket: 'YOUR_PROJECT_ID.appspot.com',
    iosBundleId: 'com.pawtable.app',
  );

  // -----------------------------------------------------------------------
  // Web
  // -----------------------------------------------------------------------

  /// Web Firebase configuration
  ///
  /// TO CONFIGURE: Replace with values from Firebase Console
  /// > Project Settings > Your apps > Web app
  static const FirebaseOptions web = FirebaseOptions(
    apiKey: 'YOUR_WEB_API_KEY',
    appId: '1:YOUR_PROJECT_ID:web:YOUR_WEB_MESSAGE_BINDING_HASH',
    messagingSenderId: 'YOUR_SENDER_ID',
    projectId: 'YOUR_PROJECT_ID',
    storageBucket: 'YOUR_PROJECT_ID.appspot.com',
    authDomain: 'YOUR_PROJECT_ID.firebaseapp.com',
    databaseURL: 'https://YOUR_PROJECT_ID-default-rtdb.firebaseio.com',
  );

  // -----------------------------------------------------------------------
  // macOS
  // -----------------------------------------------------------------------

  /// macOS Firebase configuration
  static const FirebaseOptions macos = FirebaseOptions(
    apiKey: 'YOUR_MACOS_API_KEY',
    appId: '1:YOUR_PROJECT_ID:macos:YOUR_MACOS_MESSAGE_BINDING_HASH',
    messagingSenderId: 'YOUR_SENDER_ID',
    projectId: 'YOUR_PROJECT_ID',
    storageBucket: 'YOUR_PROJECT_ID.appspot.com',
    iosBundleId: 'com.pawtable.app',
  );

  // -----------------------------------------------------------------------
  // Windows
  // -----------------------------------------------------------------------

  /// Windows Firebase configuration
  static const FirebaseOptions windows = FirebaseOptions(
    apiKey: 'YOUR_WINDOWS_API_KEY',
    appId: '1:YOUR_PROJECT_ID:windows:YOUR_WINDOWS_MESSAGE_BINDING_HASH',
    messagingSenderId: 'YOUR_SENDER_ID',
    projectId: 'YOUR_PROJECT_ID',
  );
}
